t=open('p043.txt',encoding='utf8').read()
for w,m in [('passion','a strong feeling of love or enthusiasm for something'),('interact','to communicate or mix with other people'),('sufism','the mystical branch of Islam that seeks closeness to Allah through love and devotion'),('mystical','having a spiritual meaning beyond ordinary understanding'),('appreciate','to value something or recognise its good qualities'),('perspective','a particular way of looking at or thinking about something')]:
    old=f'tr | {w} |'; assert re.search(re.escape(old)+r'[ ]*(\n|$)',t),w
    t=re.sub(re.escape(old)+r'[ ]*(\n|$)',lambda m_,o=old,m=m:o+' '+m+m_.group(1),t,count=1)
open('p043.txt','w',encoding='utf8',newline='\n').write(t)
